package com.fakelegacy.order.client;

import java.math.BigDecimal;
import java.util.LinkedHashMap;
import java.util.Map;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.HttpMethod;
import org.springframework.stereotype.Component;
import org.springframework.web.client.RestTemplate;

@Component
public class CustomerClient {

    @Autowired
    private RestTemplate rest;

    @Value("${customer.service.url}")
    private String baseUrl;

    public RemoteResult getCustomer(long id) {
        return RemoteSupport.call(rest, HttpMethod.GET, baseUrl + "/customers/" + id, null);
    }

    public RemoteResult earn(long id, int points, String orderRef) {
        Map<String, Object> body = new LinkedHashMap<>();
        body.put("points", points);
        body.put("orderRef", orderRef);
        return RemoteSupport.call(rest, HttpMethod.POST, baseUrl + "/customers/" + id + "/loyalty/earn", body);
    }

    /** points > 0 spends, points < 0 gives points back. */
    public RemoteResult redeem(long id, int points, BigDecimal orderAmount, String orderRef) {
        Map<String, Object> body = new LinkedHashMap<>();
        body.put("points", points);
        body.put("orderAmount", orderAmount);
        body.put("orderRef", orderRef);
        return RemoteSupport.call(rest, HttpMethod.POST, baseUrl + "/customers/" + id + "/loyalty/redeem", body);
    }

    /** amount > 0 consumes credit, amount < 0 releases it. */
    public RemoteResult consumeCredit(long id, BigDecimal amount) {
        Map<String, Object> body = new LinkedHashMap<>();
        body.put("amount", amount);
        return RemoteSupport.call(rest, HttpMethod.POST, baseUrl + "/customers/" + id + "/credit/consume", body);
    }
}
